body,
.color-base,
.color-primary,
.color-secondary,
.color-dark {
  color: var(--color-text);
  background-color: var(--color-background);
}
.spaced-section.color-primary + .spaced-section:not(.color-primary) {
  padding-top: var(--spacing);
}

.spaced-section.color-secondary + .spaced-section:not(.color-secondary) {
  padding-top: var(--spacing);
}

.spaced-section.color-dark + .spaced-section:not(.color-dark) {
  padding-top: var(--spacing);
}


table,
table td:not(:first-of-type)::before,
table td:first-of-type::before,
table td:last-of-type::after {
  background-color: var(--color-surface);
}


      *,
      *::before,
      *::after {
        box-sizing: inherit;
      }

      html {
        box-sizing: border-box;
        height: 100%;
      }

      body {
        display: grid;
        grid-template-rows: auto auto 1fr auto;
        grid-template-columns: 100%;
        min-height: 100%;
        margin: 0;
        font-size: 1rem;
        line-height: 1.4;
        font-family: var(--font-body-family);
        font-style: var(--font-body-style);
        font-weight: var(--font-body-weight);
      }

.shopify-pc__banner__dialog h2 {
  color: hsl(0deg, 0%, 12%, 100%);
  font-family: inherit;
  font-size: 120%;
  margin: 0 0 .5em 0;
  padding: 0;
  font-weight: bold;
}
.shopify-pc__banner__dialog p {
  color: hsl(0deg, 0%, 12%, 100%);
  font-family: inherit;
  line-height: 1.3;
  margin: 0;
  padding: 0;
}
.shopify-pc__banner__dialog a {
  color: hsl(0deg, 0%, 12%, 100%);
  text-decoration: underline;
}
.shopify-pc__banner__dialog button {
  border: none;
  text-decoration: none;
  font-family: inherit;
  padding: 8px 25px;
  /* RTL mirrors this margin in getCSSForBannerPlacement (rtlDefaultButtons). */
  margin: 15px 20px 0 0;
  font-size: 100%;
  flex-basis: 50%;
  border-radius: 2px;
  line-height: 120%;
  height: unset;
  text-align: center;
}
.shopify-pc__banner__dialog button:focus {
  outline: none;
  box-shadow: 0 0 0 4px hsl(201deg, 90%, 80%, 100%);
}
.shopify-pc__banner__dialog button:hover {
  cursor: pointer;
}
.shopify-pc__banner__dialog button.shopify-pc__banner__btn-accept {
  border: 1px solid hsl(0deg, 0%, 12%, 100%);

background: #fff;
color: #333;

}
.shopify-pc__banner__dialog button.shopify-pc__banner__btn-manage-prefs {
  text-decoration: underline;

background: transparent;
border: none;
